    mov [ebp + wJoyIgnore], al
FuchsiaGymReceiveTM06:
    mov al, TEXT_FUCHSIAGYM_KOGA_SOUL_BADGE_INFO
    mov [ebp + hTextID], al
    call DisplayTextID
    pushfd    ; SM83 form writes no flags
        SetEvent EVENT_BEAT_KOGA
    popfd
